mcp__umbraco__create-document {"documentTypeId":"33d93406-3f59-470c-bcac-b3e18d76b1b1","name":"What is MCP and Why It's Awesome","parentId":"4fb322da-254c-4f29-b008-17836fd8970c","values":[{"alias":"title","editorAlias":"Umbraco.TextBox","culture":null,"segment":null,"value":"What is MCP and Why It's Awesome"},{"alias":"excerpt","editorAlias":"Umbraco.TextArea","culture":null,"segment":null,"value":"Discover how the Model Context Protocol is revolutionizing the way AI agents interact with systems and data."},{"alias":"blocks","editorAlias":"Umbraco.BlockGrid","culture":null,"segment":null,"value":{"layout":{"Umbraco.BlockGrid":[{"contentUdi":"umb://element/ea6ebe4f43e745ca941fb4cb298eb50a","settingsUdi":null},{"contentUdi":"umb://element/bf755e7d8899cd09b40cc8b7803066","settingsUdi":null}]},"contentData":[{"key":"11111111-1111-1111-1111-111111111111","contentTypeKey":"ea6ebe4f-43e7-45ca-941f-b4cb298eb50a","title":"Understanding MCP","featuredImage":[{"key":"22222222-2222-2222-2222-222222222222","mediaKey":"343e9926-ed95-4ac1-b96d-e6781e2d4560"}]},{"key":"33333333-3333-3333-3333-333333333333","contentTypeKey":"bf755e7d-8899-4cd0-9b4b-0cc8b7803066","content":{"markup":"<p><strong>MCP</strong> (Model Context Protocol) is a standard protocol that enables AI models to interact seamlessly with external systems, APIs, and data sources. It's like giving Claude superpowers to read, create, and modify content directly in applications like Umbraco.</p><p>With MCP, you can:</p><ul><li>Automate complex workflows</li><li>Integrate AI capabilities into your systems</li><li>Maintain consistency and control through a single interface</li><li>Scale your content operations effortlessly</li></ul>","blocks":{"layout":{},"contentData":[],"settingsData":[],"expose":[]}}}],"settingsData":[],"expose":[]}}]} 

mcp__umbraco__create-document {"documentTypeId":"33d93406-3f59-470c-bcac-b3e18d76b1b1","name":"Building the Future with MCP and Umbraco","parentId":"4fb322da-254c-4f29-b008-17836fd8970c","values":[{"alias":"title","editorAlias":"Umbraco.TextBox","culture":null,"segment":null,"value":"Building the Future with MCP and Umbraco"},{"alias":"excerpt","editorAlias":"Umbraco.TextArea","culture":null,"segment":null,"value":"Learn how MCP transforms Umbraco content management by enabling AI-powered automation and intelligent workflows."},{"alias":"blocks","editorAlias":"Umbraco.BlockGrid","culture":null,"segment":null,"value":{"layout":{"Umbraco.BlockGrid":[{"contentUdi":"umb://element/ea6ebe4f43e745ca941fb4cb298eb50a","settingsUdi":null},{"contentUdi":"umb://element/bf755e7d8899cd09b40cc8b7803066","settingsUdi":null}]},"contentData":[{"key":"44444444-4444-4444-4444-444444444444","contentTypeKey":"ea6ebe4f-43e7-45ca-941f-b4cb298eb50a","title":"The Power of Integration","featuredImage":[{"key":"55555555-5555-5555-5555-555555555555","mediaKey":"9e7906f6-f4e5-45a8-9122-0d361bf7c8c5"}]},{"key":"66666666-6666-6666-6666-666666666666","contentTypeKey":"bf755e7d-8899-4cd0-9b4b-0cc8b7803066","content":{"markup":"<p>When you combine <strong>MCP</strong> with <strong>Umbraco</strong>, you unlock incredible possibilities for content creators and developers alike.</p><p>Imagine being able to:</p><ul><li>Create and publish content through intelligent AI assistance</li><li>Automate repetitive content tasks</li><li>Query your content programmatically through natural language</li><li>Build smarter workflows with AI at the center</li></ul><p>This is not science fiction—it's happening right now with MCP. The protocol provides a standardized way for AI models to understand and interact with your Umbraco instance as if they were a native user.</p>","blocks":{"layout":{},"contentData":[],"settingsData":[],"expose":[]}}}],"settingsData":[],"expose":[]}}]} 

